import math

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    num = 1
    for i in range(r):
        num = num * (n - i) // (i + 1)
    return num

def check_condition(n):
    if math.gcd(n, 6) != 1:
        return False

    # Find all positive integers a such that floor(n/a) = 2
    # This means 2 <= n/a < 3, so n/3 < a <= n/2
    a_min = n // 3 + 1
    a_max = n // 2

    for a in range(a_min, a_max + 1):
        k = n - 2*a
        if k == 0:
            # The problem says "multiple of n-2a", which is 0.
            # Since n is odd, k will never be 0.
            continue

        if nCr(a - 1, k - 1) % k != 0:
            return False

    return True

count = 0
results = []
for n in range(2, 200):
    if check_condition(n):
        count += 1
        results.append(n)

print(f"Count: {count}")
print(f"Results: {results}")
